from __future__ import annotations

"""Top-level entry point that runs one sponsored-search auction end to end.

Flow for one query:

1. Filter bids through the reserve / ad-rank threshold; ineligible ads are set
   aside with a reason and never charged.
2. Rank the eligible ads by ad rank, highest first, ties broken by id.
3. Fill the page's slots from the top of the ranking.
4. Price each winner under the generalized second price against the ad below it.
5. Bundle winners, prices, and the excluded list into one result.

The coordinator wires the policy, ranking, allocator, and pricing layers
together. It does not itself compute ad rank or prices; it asks each layer in
turn and assembles the answer.
"""

from ad_rank import order_ranked
from auction_models import AuctionConfig, AuctionResult, Bid
from eligibility_policy import partition_bids
from money import DEFAULT_INCREMENT_MICROS
from slot_allocator import allocate_slots, non_winning


def run_auction(query: str, bids: list[Bid], config: AuctionConfig) -> AuctionResult:
    """Run a full auction for ``query`` and return its result."""

    if not isinstance(query, str) or not query.strip():
        raise ValueError("query is required")

    eligible_bids, excluded = partition_bids(bids, config.reserve_micros)
    ranked = order_ranked(_rank(eligible_bids))

    slots = allocate_slots(
        ranked,
        config.num_slots,
        config.reserve_micros,
        config.increment_micros or DEFAULT_INCREMENT_MICROS,
    )

    winner_ids = {slot.advertiser_id for slot in slots}
    for ad in non_winning(ranked, config.num_slots):
        if ad.advertiser_id not in winner_ids:
            excluded.append(
                {
                    "advertiser_id": ad.advertiser_id,
                    "reason": "no_slot_available",
                    "ad_rank": ad.ad_rank,
                    "reserve_micros": config.reserve_micros,
                }
            )

    result = AuctionResult(query=query, slots=slots, excluded=excluded)
    result.fields["eligible_count"] = len(eligible_bids)
    result.fields["slot_count"] = len(slots)
    result.fields["num_slots"] = config.num_slots
    return result


def _rank(bids: list[Bid]):
    from ad_rank import rank_eligible_ads

    return rank_eligible_ads(bids)


class AuctionCoordinator:
    """A reusable runner that carries a config and remembers past auctions."""

    def __init__(self, config: AuctionConfig) -> None:
        self.config = config
        self._history: list[AuctionResult] = []

    def run(self, query: str, bids: list[Bid]) -> AuctionResult:
        result = run_auction(query, bids, self.config)
        self._history.append(result)
        return result

    def history(self) -> list[AuctionResult]:
        return list(self._history)

    def total_revenue(self) -> int:
        return sum(result.total_charged() for result in self._history)

    def last(self) -> AuctionResult | None:
        if not self._history:
            return None
        return self._history[-1]

