from __future__ import annotations

"""Domain models for a sponsored-search ad auction.

A search query opens an auction with a fixed number of ad slots. Each
advertiser submits a single entry for that query: a maximum cost-per-click bid
(integer micros) and a quality score the platform assigns to that ad for that
query. The two combine into an *ad rank*, which decides both who shows and what
order they show in.

Money is integer micros everywhere (see ``money``). Quality score is a small
positive integer on a fixed scale (1..10 in practice, but the models only
require it to be positive). Nothing here computes ad rank, ranks anything, or
prices a click; those live in the ad-rank, pricing, eligibility, and allocator
layers. These are plain value objects with validation and a few convenience
views the other layers and the tests read.
"""

from dataclasses import dataclass, field, replace

from money import is_positive_micros


# A quality score is constrained to this inclusive scale for a real query.
MIN_QUALITY = 1
MAX_QUALITY = 10


def _require_text(value: str, name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} is required")


def _require_quality(value: int, name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an int")
    if value < MIN_QUALITY or value > MAX_QUALITY:
        raise ValueError(f"{name} must be within {MIN_QUALITY}..{MAX_QUALITY}")


@dataclass(frozen=True)
class Advertiser:
    """An account competing for a slot on one query.

    ``advertiser_id`` is the deterministic tie-break key: when two ads have the
    same ad rank, the lexicographically smaller id ranks higher.
    """

    advertiser_id: str
    name: str = ""

    def __post_init__(self) -> None:
        _require_text(self.advertiser_id, "advertiser_id")

    def display_name(self) -> str:
        return self.name.strip() or self.advertiser_id


@dataclass(frozen=True)
class Bid:
    """One advertiser's entry in an auction.

    ``max_cpc_micros`` is the most the advertiser is willing to pay per click.
    ``quality_score`` is the platform's estimate of this ad's quality for the
    query. The actual price charged is computed later and is at most the max
    bid.
    """

    advertiser_id: str
    max_cpc_micros: int
    quality_score: int

    def __post_init__(self) -> None:
        _require_text(self.advertiser_id, "advertiser_id")
        if not is_positive_micros(self.max_cpc_micros):
            raise ValueError("max_cpc_micros must be a positive int of micros")
        _require_quality(self.quality_score, "quality_score")

    def with_max_cpc(self, max_cpc_micros: int) -> "Bid":
        return replace(self, max_cpc_micros=max_cpc_micros)

    def with_quality(self, quality_score: int) -> "Bid":
        return replace(self, quality_score=quality_score)


@dataclass(frozen=True)
class RankedAd:
    """A bid after its ad rank has been computed, ready to be ordered.

    ``ad_rank`` is the value the ranking layer sorts by, descending. ``eligible``
    records whether the ad cleared the reserve / ad-rank threshold. An ineligible
    ad never takes a slot and is never charged.
    """

    advertiser_id: str
    max_cpc_micros: int
    quality_score: int
    ad_rank: int
    eligible: bool = True

    def sort_key(self) -> tuple:
        """Sort descending by ad rank, breaking ties by ascending id.

        Returning a negative ad rank lets callers sort ascending on this key and
        still get highest ad rank first, with the smaller id winning a tie.
        """

        return (-self.ad_rank, self.advertiser_id)


@dataclass(frozen=True)
class AuctionSlot:
    """One filled position in the results page.

    ``position`` is zero-based (0 is the top slot). ``price_micros`` is the
    cost-per-click charged to the winner of this slot, already capped at the
    winner's max bid and floored at the reserve.
    """

    position: int
    advertiser_id: str
    ad_rank: int
    quality_score: int
    max_cpc_micros: int
    price_micros: int

    def __post_init__(self) -> None:
        if self.position < 0:
            raise ValueError("position must be non-negative")
        if self.price_micros < 0:
            raise ValueError("price_micros must be non-negative")
        if self.price_micros > self.max_cpc_micros:
            raise ValueError("price_micros must not exceed max_cpc_micros")


@dataclass
class AuctionConfig:
    """Knobs for one auction.

    ``num_slots`` is how many ad positions the page exposes. ``reserve_micros``
    is the floor price a click can be charged and also the ad-rank threshold an
    ad must clear to be eligible. ``increment_micros`` is the bid step the second
    price is rounded up to.
    """

    num_slots: int = 1
    reserve_micros: int = 10_000
    increment_micros: int = 10_000

    def __post_init__(self) -> None:
        if self.num_slots < 0:
            raise ValueError("num_slots must be non-negative")
        if self.reserve_micros < 0:
            raise ValueError("reserve_micros must be non-negative")
        if self.increment_micros <= 0:
            raise ValueError("increment_micros must be positive")


@dataclass
class AuctionResult:
    """The outcome of one auction.

    ``slots`` are the filled positions in display order. ``excluded`` lists the
    advertiser ids that did not show (ineligible or no slot left), each with a
    reason. ``fields`` is a free bag the audit layer can attach extra data to.
    """

    query: str
    slots: list[AuctionSlot] = field(default_factory=list)
    excluded: list[dict] = field(default_factory=list)
    fields: dict = field(default_factory=dict)

    def winner_ids(self) -> list[str]:
        return [slot.advertiser_id for slot in self.slots]

    def total_charged(self) -> int:
        return sum(slot.price_micros for slot in self.slots)

    def price_for(self, advertiser_id: str) -> int | None:
        for slot in self.slots:
            if slot.advertiser_id == advertiser_id:
                return slot.price_micros
        return None

    def slot_at(self, position: int) -> AuctionSlot | None:
        for slot in self.slots:
            if slot.position == position:
                return slot
        return None


def build_bid(advertiser_id: str, max_cpc_micros: int, quality_score: int) -> Bid:
    return Bid(
        advertiser_id=advertiser_id,
        max_cpc_micros=max_cpc_micros,
        quality_score=quality_score,
    )


def build_config(
    num_slots: int = 1,
    reserve_micros: int = 10_000,
    increment_micros: int = 10_000,
) -> AuctionConfig:
    return AuctionConfig(
        num_slots=num_slots,
        reserve_micros=reserve_micros,
        increment_micros=increment_micros,
    )

