from __future__ import annotations

"""Read-only auditing over auction outcomes.

Finance and ads-quality both want to look at an auction after it ran: who won,
what each winner paid, how much headroom there was between the price and the
winner's max bid, and which ads were filtered out and why. Overcharging shows up
here as zero headroom across the board (every winner paying their cap) or as a
charged price that does not match the second-price basis recorded for it.

Nothing in this module re-runs an auction or recomputes a price. It reads the
result the coordinator already produced and the per-winner pricing breakdown the
pricing engine recorded, then rolls them up into plain dictionaries and a short
line an on-call engineer can paste into a ticket.
"""

from collections import Counter

from auction_models import AuctionResult
from money import format_micros
from pricing_engine import headroom


def revenue(result: AuctionResult) -> int:
    """Total micros charged across all filled slots."""

    return result.total_charged()


def headroom_by_winner(result: AuctionResult) -> dict:
    """How far below each winner's max bid the charged price landed."""

    out: dict = {}
    for slot in result.slots:
        gap = max(0, slot.max_cpc_micros - slot.price_micros)
        out[slot.advertiser_id] = gap
    return out


def all_winners_paid_cap(result: AuctionResult) -> bool:
    """Whether every winner paid exactly their max bid.

    A healthy second-price auction almost never charges every winner their cap;
    when it does for a competitive auction, prices collapsed to first-price.
    """

    if not result.slots:
        return False
    return all(slot.price_micros == slot.max_cpc_micros for slot in result.slots)


def exclusion_reasons(result: AuctionResult) -> dict:
    """Count excluded ads by reason."""

    counts: Counter = Counter()
    for entry in result.excluded:
        counts[entry.get("reason", "unknown")] += 1
    return dict(counts)


def winner_price_table(result: AuctionResult) -> list[dict]:
    """A per-winner table of price, cap, and headroom for review."""

    table = []
    for slot in result.slots:
        gap = max(0, slot.max_cpc_micros - slot.price_micros)
        table.append(
            {
                "position": slot.position,
                "advertiser_id": slot.advertiser_id,
                "price_micros": slot.price_micros,
                "max_cpc_micros": slot.max_cpc_micros,
                "headroom_micros": gap,
                "price_display": format_micros(slot.price_micros),
            }
        )
    return table


def audit_bundle(result: AuctionResult) -> dict:
    """Roll one auction up into a single audit report."""

    return {
        "query": result.query,
        "winner_ids": result.winner_ids(),
        "revenue_micros": revenue(result),
        "headroom_by_winner": headroom_by_winner(result),
        "all_winners_paid_cap": all_winners_paid_cap(result),
        "exclusion_reasons": exclusion_reasons(result),
        "filled_slots": len(result.slots),
    }


def render_audit_line(result: AuctionResult) -> str:
    """A one-line human summary of an auction outcome."""

    bundle = audit_bundle(result)
    return (
        f"{bundle['query']}: {bundle['filled_slots']} slots, "
        f"{len(result.excluded)} excluded, "
        f"revenue {format_micros(bundle['revenue_micros'])}"
    )


def headroom_for(result: AuctionResult, advertiser_id: str) -> int | None:
    """Headroom for a single winner, or ``None`` if they did not win."""

    for slot in result.slots:
        if slot.advertiser_id == advertiser_id:
            return headroom(slot, slot.price_micros)
    return None

